<script setup lang="ts">
import{ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{authRequest}from'../../api/client'
const router=useRouter(),route=useRoute(),mode=ref<'login'|'register'>('login'),loading=ref(false)
const form=ref({email:'',password:'',display_name:'',country:'US',language:'en'})
async function submit(){if(!form.value.email||form.value.password.length<8){ElMessage.warning('请输入有效邮箱和至少 8 位密码');return}loading.value=true;try{const r=await authRequest('/api/v1/auth/'+mode.value,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});localStorage.setItem('auth_token',r.token);localStorage.setItem('user_id',String(r.user.id));localStorage.setItem('auth_user',JSON.stringify(r.user));ElMessage.success(mode.value==='login'?'登录成功':'注册成功');router.replace(String(route.query.redirect||'/home'))}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
</script>
<template><section class="auth-page"><el-card class="auth-card"><p class="eyebrow">SHORT DRAMA ACCOUNT</p><h1>{{mode==='login'?'Welcome back':'Create your account'}}</h1><p>登录后即可购买短剧并同步观看权益。</p><el-form @submit.prevent="submit"><el-form-item label="Email"><el-input v-model="form.email" type="email" autocomplete="email"/></el-form-item><el-form-item label="Password"><el-input v-model="form.password" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item v-if="mode==='register'" label="昵称"><el-input v-model="form.display_name"/></el-form-item><el-button type="primary" size="large" :loading="loading" class="pay-btn" @click="submit">{{mode==='login'?'登录':'注册'}}</el-button></el-form><el-button text @click="mode=mode==='login'?'register':'login'">{{mode==='login'?'没有账号？注册':'已有账号？登录'}}</el-button></el-card></section></template>